import { test, expect } from '@playwright/test';

// 純計算：有效數字先 Math.round 再夾至 0..100；非有限 number 拋 TypeError
function normalizeScore(value: unknown): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new TypeError('normalizeScore expects a finite number');
  }
  const rounded = Math.round(value as number);
  return Math.min(100, Math.max(0, rounded));
}

test('normalizeScore 十個邊界案例', async () => {
  await test.step('輸入型別：非有限 number 拋 TypeError', async () => {
    expect(() => normalizeScore('12')).toThrow(TypeError);
    expect(() => normalizeScore(NaN)).toThrow(TypeError);
    expect(() => normalizeScore(Infinity)).toThrow(TypeError);
  });

  await test.step('四捨五入：0.49→0、0.5→1、99.49→99、99.5→100', async () => {
    expect(normalizeScore(0.49)).toBe(0);
    expect(normalizeScore(0.5)).toBe(1);
    expect(normalizeScore(99.49)).toBe(99);
    expect(normalizeScore(99.5)).toBe(100);
  });

  await test.step('上下界夾值：-1→0、0→0、101→100', async () => {
    expect(normalizeScore(-1)).toBe(0);
    expect(normalizeScore(0)).toBe(0);
    expect(normalizeScore(101)).toBe(100);
  });
});

